  	UPDATE FASCICOLO_SIEP A
  	SET A.KEY_PROVV_NSC = NULL
		WHERE A.ID_FASCICOLO_SIEP = #{sies}

  	UPDATE FASCICOLO_SIEP A
  	SET A.KEY_PROVV_NSC = #{nsc}
		WHERE A.ID_FASCICOLO_SIEP = #{sies}
  	AND A.KEY_PROVV_NSC IS NULL

