SELECT ID_ISTRUTTORIA_CUMULO
  FROM ISTRUTTORIA_CUMULO
 WHERE FAS_SIE_ID_FASCICOLO_SIEP = #{idFascicoloSiep}
   AND EVE_ID_EVENTO_PROV = #{idEvento}
   AND DATA_CHIUSURA IS NOT NULL
   AND FLAG_STATO = 'C'
